//! ORDER item 3: the coverage completeness gate.
//!
//! The manifests in tests/coverage/ are generated by
//! Lykaon/tools/extract_coverage.py from the book (Appendix B, Reference 2,
//! Reference 3, Reference 7, milestone appendices I..N). This test is the
//! automatic completeness check: it fails when any M1-M4 grammar,
//! diagnostic, semantic or IR item lacks a test, and it fails when an M5+
//! item is not marked reserved with the "gives T0509" note.
//!
//! The missing rows are the work list: fill them by priority (M1/M2 core
//! syntax first, then M3, then M4) by writing tests that cite the item id,
//! and regenerate the manifests with the extractor. Until the list is
//! empty this suite is RED on purpose: the build must not claim M4
//! verification while items lack tests.

use std::path::Path;

#[path = "coverage/manifest.rs"]
mod manifest;

use manifest::{Item, load};

const ROOT: &str = "tests/coverage";

fn is_m4_or_earlier(milestone: &str) -> bool {
    matches!(milestone, "M1a" | "M1b" | "M2" | "M3" | "M4")
}

#[test]
fn coverage_manifests_are_complete() {
    let dir = Path::new(ROOT);
    let grammar = load(&dir.join("grammar.json"));
    let diagnostics = load(&dir.join("diagnostics.json"));
    let semantic = load(&dir.join("semantic.json"));
    let ir = load(&dir.join("ir.json"));

    let mut failures: Vec<String> = Vec::new();

    let groups: [(&str, &[Item]); 4] = [
        ("grammar", &grammar),
        ("diagnostics", &diagnostics),
        ("semantic", &semantic),
        ("ir", &ir),
    ];
    for (kind, items) in groups {
        for it in items {
            match it.status.as_str() {
                "covered" => {}
                "reserved" => {
                    // an M5+ row must say why it is reserved
                    if it.note.as_deref() != Some("reserved: gives T0509") {
                        failures.push(format!(
                            "{}: {} is reserved without the T0509 note",
                            kind, it.id
                        ));
                    }
                    if is_m4_or_earlier(&it.milestone) {
                        failures.push(format!(
                            "{}: {} is an M1-M4 row marked reserved",
                            kind, it.id
                        ));
                    }
                }
                "missing" => {
                    if is_m4_or_earlier(&it.milestone) {
                        failures.push(format!(
                            "{}: {} ({}) has no test",
                            kind, it.id, it.milestone
                        ));
                    }
                }
                "unreachable" => {
                    if is_m4_or_earlier(&it.milestone) {
                        failures.push(format!(
                            "{}: {} ({}) is implemented but no test cites it",
                            kind, it.id, it.milestone
                        ));
                    }
                }
                other => failures.push(format!("{}: {} has unknown status {}", kind, it.id, other)),
            }
        }
    }

    assert!(
        failures.is_empty(),
        "coverage completeness failures ({}):\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// The generated report must exist and must agree with the manifests
/// (the row counts per kind), so a stale REPORT.md fails too.
#[test]
fn coverage_report_is_fresh() {
    let dir = Path::new(ROOT);
    let grammar = load(&dir.join("grammar.json"));
    let diagnostics = load(&dir.join("diagnostics.json"));
    let semantic = load(&dir.join("semantic.json"));
    let ir = load(&dir.join("ir.json"));
    let report = std::fs::read_to_string(dir.join("REPORT.md"))
        .expect("tests/coverage/REPORT.md is generated by the extractor");
    let groups: [(&str, &[Item], &str); 4] = [
        ("grammar", &grammar, "## Grammar"),
        ("diagnostics", &diagnostics, "## Diagnostics"),
        ("semantic", &semantic, "## Semantic rules"),
        ("ir", &ir, "## MIR opcodes"),
    ];
    for (_, items, heading) in groups {
        let want = format!("- rows: {}", items.len());
        assert!(
            report.contains(&want),
            "REPORT.md is stale: {} missing under {}",
            want,
            heading
        );
    }
}

/// The implementation-side map (src/coverage_map.rs) must list exactly the
/// non-reserved M1-M4 grammar and semantic rows of the manifests: the map
/// is the citation the coverage grep finds, so drift between the two files
/// would silently change the gate.
#[test]
fn coverage_map_matches_the_manifests() {
    let dir = Path::new(ROOT);
    let grammar = load(&dir.join("grammar.json"));
    let semantic = load(&dir.join("semantic.json"));
    let map = std::fs::read_to_string("src/coverage_map.rs")
        .expect("src/coverage_map.rs is generated by the extractor");

    let mut map_ids: Vec<String> = Vec::new();
    // the tuples may be single-line or rustfmt-wrapped: take the first
    // quoted string after every "("
    for part in map.split('(') {
        if let Some(start) = part.find('"') {
            if let Some(end) = part[start + 1..].find('"') {
                map_ids.push(part[start + 1..start + 1 + end].to_string());
            }
        }
    }
    map_ids.retain(|id| {
        let mut chars = id.chars();
        let first = chars.next().unwrap_or(' ');
        let rest: String = chars.collect();
        matches!(first, 'G' | 'S' | 'M')
            && !rest.is_empty()
            && rest.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
            && rest.chars().any(|c| c.is_ascii_digit())
    });

    let mut want: Vec<String> = grammar
        .iter()
        .chain(semantic.iter())
        .filter(|it| it.status != "reserved" && is_m4_or_earlier(&it.milestone))
        .map(|it| it.id.clone())
        .collect();
    want.sort();
    map_ids.sort();
    assert_eq!(
        want, map_ids,
        "src/coverage_map.rs and the manifests disagree; rerun Lykaon/tools/extract_coverage.py"
    );
}
